// Pega os dados de entrada
const item = $input.item;

// 1. Ler o CÓDIGO (agora é um TEXTO simples do formulário)
let code = "";
try {
  // DADOS AGORA VÊM DO JSON, NÃO DO BINARY
  // O nome do campo é 'Insira aqui'
  if (!item.json || !item.json['Insira aqui']) {
    throw new Error("O campo 'Insira aqui' está vazio ou não foi encontrado.");
  }

  // A linha mais importante: apenas lemos o texto.
  code = item.json['Insira aqui'];

} catch (error) {
  // Se falhar a leitura, retorna um erro
  return { error: "Falha ao ler o código do formulário. " + error.message };
}

// 2. Nossos padrões de Regex (Regras de Detecção)
// ESTA PARTE NÃO MUDA. O Regex opera em texto.
const patterns = {
  SQL_INJECTION: /(SELECT\s+.*\s+WHERE\s+.*\s*['"]\s*[\.+]\s*(\w+))/gi,
  COMMAND_INJECTION: /(exec|system|shell_exec|passthru)\s*\(\s*.*?(\$\w+)/gi
};

let findings = []; // Uma lista simples de achados

// 3. Testar os padrões (NÃO MUDA)
if (patterns.SQL_INJECTION.test(code)) {
  findings.push("Potencial SQL Injection (Concatenação de String)");
}

if (patterns.COMMAND_INJECTION.test(code)) {
  findings.push("Potencial Command Injection (Uso de função perigosa)");
}

// 4. Retornar a lista de achados para o próximo nó (NÃO MUDA)
return {
  findings: findings
};
